import {captureRack,serializeRack,parseRack} from './war-rack10.js';
import {suggestHeadroom} from './war-rack03.js';
import {trimStage} from './war-rack07.js';
import {WAR_RACKS} from './war-rack-catalog.js';import {matchesTarget,planRack,applyRack} from './war-rack-core.js';
export function filterRacks(catalog,{track,stage='all',source='all',genre='all',query=''}={}){const q=query.trim().toLowerCase();return catalog.filter(r=>matchesTarget(r,track)&&(stage==='all'||r.stage===stage)&&(source==='all'||r.source===source)&&(genre==='all'||r.genre===genre||r.genre==='Tous')&&[r.name,r.source,r.genre,r.description].join(' ').toLowerCase().includes(q));}
export function mountRackBrowser(root,{track,project,apply,measureSource}){root.innerHTML='<div class="mix-master-template-picker"><p>Un preset = une chaîne native ordonnée. Les paramètres restent modifiables dans les fenêtres individuelles.</p><div><button type="button" class="outline-btn" data-save>Enregistrer la chaîne actuelle (.json)</button> <label>Importer un preset <input type="file" data-import accept=".json,application/json"></label></div><div class="mix-master-template-filters"><label>Étape<select data-stage></select></label><label>Source<select data-source></select></label><label>Genre<select data-genre></select></label><label>Recherche<input type="search" data-query></label></div><div class="mix-master-template-content"><div data-list class="mix-master-template-list"></div><section class="mix-master-template-detail"><h3 data-name></h3><p data-desc></p><ol data-chain></ol><label>Mode<select data-mode><option value="replace">Remplacer</option><option value="append">Ajouter</option></select></label><button type="button" class="outline-btn" data-measure hidden>Mesurer le gain de la source</button><button type="button" class="primary-btn" data-apply>Appliquer le rack</button><p role="status"></p></section></div></div>';const $=s=>root.querySelector(s),stage=$('[data-stage]'),source=$('[data-source]'),genre=$('[data-genre]'),mode=$('[data-mode]'),button=$('[data-apply]'),status=$('[role=status]');let catalog=[...WAR_RACKS];const candidates=catalog.filter(r=>matchesTarget(r,track));const fill=(el,values)=>{el.replaceChildren(new Option('Tous','all'),...values.map(v=>new Option(v,v)))};fill(stage,[...new Set(candidates.map(r=>r.stage))]);fill(source,[...new Set(candidates.map(r=>r.source))].sort());fill(genre,[...new Set(candidates.map(r=>r.genre))].sort());if(!track)mode.disabled=true;let selected=null,adapted=null;function render(){const rows=filterRacks(catalog,{track,stage:stage.value,source:source.value,genre:genre.value,query:$('[data-query]').value});if(!rows.includes(selected)){selected=rows[0]||null;adapted=null;}$('[data-list]').replaceChildren(...rows.map(r=>{const b=document.createElement('button');b.className='mix-master-template-option';b.type='button';b.textContent=r.name+' · '+r.source;b.setAttribute('aria-pressed',String(r===selected));b.onclick=()=>{selected=r;adapted=null;render()};return b}));$('[data-name]').textContent=selected?.name||'Aucun rack';$('[data-desc]').textContent=selected?.description||'';$('[data-chain]').replaceChildren();button.disabled=true;status.textContent='';$('[data-measure]').hidden=!(measureSource&&selected?.stage==='premix');if(!selected)return;try{const plan=planRack(adapted||selected,{track,project,mode:mode.value});for(const p of plan.stages){const li=document.createElement('li');li.textContent=p.name+' — '+Object.entries(p.values).map(([k,v])=>k+': '+v).join(' · ');$('[data-chain]').append(li)}status.textContent=plan.stages.length+' plugins / '+plan.available+' places';button.disabled=false}catch(e){status.textContent=e.message}}for(const el of [stage,source,genre,mode])el.onchange=render;$('[data-query]').oninput=render;button.onclick=async()=>{button.disabled=true;try{await apply(adapted||selected,mode.value,applyRack)}catch(e){status.textContent=e.message}finally{button.disabled=false}};
$('[data-save]').onclick=()=>{try{const label=prompt('Nom du preset',selected?.name||track?.name||'Master');if(!label?.trim())return;const r=captureRack({track,project,name:label,source:selected?.source|| (track?.type==='bus'?'Bus':track?.type==='audio'?'Lead Vocal':track?.type==='drums'?'Drums':track?'Other':'Master'),stage:selected?.stage|| (track?'mix':'master'),genre:selected?.genre||'Tous'});const url=URL.createObjectURL(new Blob([serializeRack(r)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='war-rack.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Chaîne active enregistrée; inserts bypassés exclus.';}catch(e){status.textContent=e.message}};
$('[data-import]').onchange=async()=>{try{const file=$('[data-import]').files[0];if(!file||file.size>262144)throw Error('Fichier absent ou trop volumineux');const r=parseRack(await file.text());if(!matchesTarget(r,track))throw Error('Preset incompatible avec la destination');catalog=[...catalog.filter(x=>x.id!==r.id),r];for(const [el,v] of [[stage,r.stage],[source,r.source],[genre,r.genre]])if(![...el.options].some(o=>o.value===v))el.append(new Option(v,v));stage.value=source.value=genre.value='all';$('[data-query]').value='';selected=r;adapted=null;render();}catch(e){status.textContent=e.message}};
$('[data-measure]').onclick=async()=>{const r=selected,m=$('[data-measure]');m.disabled=true;try{const result=suggestHeadroom(await measureSource());if(selected!==r)return;if(result.gainDb===null)throw Error('Source silencieuse, saturée ou invalide : corriger avant le rack.');if(result.gainDb< -12)throw Error('Réduction conseillée '+result.gainDb.toFixed(1)+' dB : corrige le niveau source avant la chaîne (trim limité à 12 dB).');const stages=r.stages.map(s=>s.id==='tilteq'?trimStage(result.gainDb):s);adapted={...r,stages:stages.some(s=>s.id==='tilteq')?stages:[trimStage(result.gainDb),...stages]};render();status.textContent='Crête source '+result.peakDb.toFixed(1)+' dBFS · trim proposé '+result.gainDb.toFixed(1)+' dB; appliquer pour confirmer.';}catch(e){status.textContent=e.message}finally{m.disabled=false}};render();}